def orbit(r,c,n):
    return {(r,c),(r,n-1-c),(n-1-r,c),(n-1-r,n-1-c),(c,r),(c,n-1-r),(n-1-c,r),(n-1-c,n-1-r)}
errs=[]; ambiguous=[]
for r in range(24):
  for c in range(24):
    if demo_in[r][c]==2:
      vals={demo_in[a][b] for a,b in orbit(r,c,24) if demo_in[a][b]!=2}
      if len(vals)!=1: ambiguous.append((r,c,vals))
      elif next(iter(vals))!=demo_out[r][c]: errs.append((r,c,next(iter(vals)),demo_out[r][c]))
print('ambiguous',len(ambiguous),ambiguous[:20], 'errs',len(errs),errs[:20])
